import assert from "node:assert/strict";
import { test } from "node:test";
import { compareSemver } from "../src/semver.ts";

test("grader: compareSemver", () => {
  assert.equal(compareSemver("1.10.0", "1.9.0"), 1);
  assert.equal(compareSemver("1.9.0", "1.10.0"), -1);
  assert.equal(compareSemver("1.0.0", "1.0.0"), 0);
  assert.equal(compareSemver("0.9.9", "1.0.0"), -1);
  assert.equal(compareSemver("2.0.0", "1.99.99"), 1);
  assert.throws(() => compareSemver("1.0", "1.0.0"));
  assert.throws(() => compareSemver("a.b.c", "1.0.0"));
});

