export const SEMVER_RE = /^(\d+)\.(\d+)\.(\d+)$/;

export function compareSemver(a: string, b: string): -1 | 0 | 1 {
  if (!SEMVER_RE.test(a)) throw new Error(`invalid semver: ${a}`);
  if (!SEMVER_RE.test(b)) throw new Error(`invalid semver: ${b}`);
  if (a === b) return 0;
  return a < b ? -1 : 1;
}
